#![cfg_attr(not(debug_assertions),windows_subsystem="windows")]
use serde_json::{json,Value};use std::{io::{BufRead,BufReader,Write},process::{Child,ChildStdin,Command,Stdio},sync::Mutex};use tauri::{Manager,State};use tauri_plugin_global_shortcut::{Code,GlobalShortcutExt,Modifiers,Shortcut,ShortcutState};
struct Engine{input:Mutex<Option<ChildStdin>>,child:Mutex<Option<Child>>,status:Mutex<Value>}impl Engine{fn send(&self,command:&str)->Result<(),String>{let mut guard=self.input.lock().map_err(|e|e.to_string())?;let input=guard.as_mut().ok_or("Speech engine is starting")?;writeln!(input,"{}",json!({"command":command})).map_err(|e|e.to_string())?;input.flush().map_err(|e|e.to_string())}fn error(&self,message:String){if let Ok(mut value)=self.status.lock(){*value=json!({"phase":"error","recording":false,"message":message})}}}
#[tauri::command]fn get_status(engine:State<'_,Engine>)->Result<Value,String>{engine.status.lock().map(|v|v.clone()).map_err(|e|e.to_string())}
fn main(){let shortcut=Shortcut::new(Some(Modifiers::ALT),Code::KeyP);let app=tauri::Builder::default().manage(Engine{input:Mutex::new(None),child:Mutex::new(None),status:Mutex::new(json!({"phase":"loading","recording":false,"message":"Starting…"}))}).invoke_handler(tauri::generate_handler![get_status]).plugin(tauri_plugin_global_shortcut::Builder::new().with_handler(move|app,pressed,event|{if pressed==&shortcut&&event.state()==ShortcutState::Pressed{let engine=app.state::<Engine>();if let Err(error)=engine.send("toggle"){engine.error(error)}}}).build()).setup(move|app|{app.global_shortcut().register(shortcut)?;#[cfg(target_os="linux")]{let resources=app.path().resource_dir()?.join("engine");let mut command=Command::new(resources.join("node/bin/node"));command.arg(resources.join("app/index.js")).env("WHISPER_FLOW_RESOURCES",resources.join("resources")).current_dir(&resources).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::null());match command.spawn(){Ok(mut child)=>{let output=child.stdout.take();let engine=app.state::<Engine>();*engine.input.lock().map_err(|e|e.to_string())?=child.stdin.take();*engine.child.lock().map_err(|e|e.to_string())?=Some(child);if let Some(output)=output{let handle=app.handle().clone();std::thread::spawn(move||{for line in BufReader::new(output).lines().map_while(Result::ok){if let Ok(value)=serde_json::from_str::<Value>(&line){if let Ok(mut state)=handle.state::<Engine>().status.lock(){*state=value}}}handle.state::<Engine>().error("Speech engine stopped. Restart the app.".into());});}}Err(error)=>app.state::<Engine>().error(format!("Could not start included engine: {error}")),}}#[cfg(not(target_os="linux"))]app.state::<Engine>().error("This faster-whisper-ts release supports Linux only.".into());Ok(())}).build(tauri::generate_context!()).expect("Could not start Whisper Flow");app.run(|handle,event|if let tauri::RunEvent::Exit=event{let engine=handle.state::<Engine>();let _=engine.send("quit");if let Ok(mut child)=engine.child.lock(){if let Some(mut process)=child.take(){let _=process.kill();let _=process.wait();}}});}
